package com.yuyutian.mytools.media.library.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.yuyutian.mytools.media.library.model.MediaModels.*;import com.yuyutian.mytools.media.library.repository.MediaRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.support.TransactionTemplate;
import java.nio.ByteBuffer;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.Instant;import java.util.*;import org.springframework.transaction.annotation.Isolation;import org.springframework.transaction.annotation.Transactional;
/** Media Library 领域服务。 */ @Service public class MediaLibraryService {
 private final MediaRepository repository;private final TransactionTemplate transactions;private final ObjectMapper mapper;private final MediaTaskSchedulerClient scheduler;
 /** 创建服务。 @param repository 仓储 @param transactions 事务 @param mapper JSON @param scheduler 调度客户端 */ public MediaLibraryService(MediaRepository repository,TransactionTemplate transactions,ObjectMapper mapper,MediaTaskSchedulerClient scheduler){this.repository=repository;this.transactions=transactions;this.mapper=mapper;this.scheduler=scheduler;}
 /** 消费幂等资产事件。 @param event 事件 @return 媒体 */ public MediaView consume(AssetEvent event){return transactions.execute(s->{Instant now=Instant.now();String hash=digest(event);if(!repository.acceptEvent(event.eventId(),hash,now))return repository.viewByAsset(event.ownerId(),event.assetId()).orElseThrow();return repository.merge(event,now);});}
 /** 幂等导入旧媒体及标签。 @param request 迁移请求 @return 媒体 */ public MediaView importLegacy(LegacyMediaImport request){validateTags(request.tags());return transactions.execute(s->{Instant now=Instant.now();AssetEvent event=request.event();String hash=legacyPayloadDigest(request);boolean accepted=repository.acceptEvent(event.eventId(),hash,now);MediaView media=accepted?repository.merge(event,now):repository.viewByAsset(event.ownerId(),event.assetId()).orElseThrow();if(accepted)repository.mergeLegacyTags(media.id(),event.ownerId(),event.sourceType(),event.sourceBusinessId(),request.tags(),now);repository.recordLegacyMigration(request,hash,media.id(),now);return repository.view(media.id()).orElseThrow();});}
 /** 返回本次旧媒体迁移的精确目标证据。 @param migrationKey 迁移键 @return 目标证据 */ @Transactional(readOnly=true) public LegacyMigrationEvidence legacyMigrationEvidence(String migrationKey){if(migrationKey==null||!migrationKey.matches("^[A-Za-z0-9._:-]{1,128}$"))throw new IllegalArgumentException("legacy media migration key is invalid");List<MediaRepository.LegacyMigrationRecord> records=repository.legacyMigrationRecords(migrationKey);MessageDigest digest=sha256();String snapshotId=null;int tags=0;for(var record:records){if(snapshotId==null)snapshotId=record.sourceSnapshotId();else if(!snapshotId.equals(record.sourceSnapshotId()))throw new IllegalStateException("legacy media migration snapshot conflict");update(digest,record.sourceSystem(),record.legacyAssetId(),record.payloadSha256(),Integer.toString(record.tagCount()));tags+=record.tagCount();}return new LegacyMigrationEvidence(migrationKey,snapshotId,records.size(),tags,HexFormat.of().formatHex(digest.digest()));}
 /** 幂等回填旧媒体目录关系。 @param request 回填请求 */ public void backfillLegacyDirectories(LegacyDirectoryBackfill request){transactions.executeWithoutResult(status->{Instant now=Instant.now();for(LegacyDirectoryBinding binding:request.bindings())repository.bindLegacyDirectory(binding,now);});}
 /** 查询媒体。 @param ownerId 所有者 @param id 标识 @return 媒体 */ public MediaView view(long ownerId,UUID id){MediaView value=repository.view(id).orElseThrow(()->new IllegalArgumentException("media item not found"));if(value.ownerId()!=ownerId)throw new IllegalArgumentException("media item not found");return value;}
 /** 删除当前所有者媒体投影。 @param ownerId 所有者 @param id 媒体标识 */ public void delete(long ownerId,UUID id){transactions.executeWithoutResult(s->repository.delete(ownerId,id,Instant.now()));}
 /** 分页查询所有者媒体。 @param ownerId 所有者 @param afterId 起始标识 @param includeMissing 是否包含缺失项 @param mimePrefix MIME 前缀 @param limit 页大小 @return 媒体页 */ public MediaPage list(long ownerId,UUID afterId,boolean includeMissing,String mimePrefix,int limit){if(ownerId<=0||limit<1||limit>100||mimePrefix!=null&&!mimePrefix.matches("^(image/|video/|audio/|application/|text/)$"))throw new IllegalArgumentException("media list query is invalid");List<MediaView> values=repository.list(ownerId,afterId,includeMissing,mimePrefix,limit+1);List<MediaView> page=values.stream().limit(limit).toList();UUID next=values.size()>limit&&!page.isEmpty()?page.getLast().id():null;return new MediaPage(page,next);}
 /** 同步查询媒体目录，不创建任务。 @param ownerId 所有者 @param mimePrefix MIME前缀 @param tag 标签 @param keyword 关键字 @param page 页码 @param pageSize 页大小 @param excludeAdult 是否排除成人内容 @return 媒体目录分页 */
 @Transactional(readOnly=true) public MediaCatalogPage catalog(long ownerId,String mimePrefix,String directoryId,String tag,String keyword,int page,int pageSize,boolean excludeAdult){
  if(ownerId<=0||mimePrefix==null||!mimePrefix.matches("^(image/|video/|audio/)$")||directoryId==null||directoryId.length()>255||tag==null||tag.length()>64||keyword==null||keyword.length()>100||page<1||pageSize<1||pageSize>100)throw new IllegalArgumentException("media catalog query is invalid");
  int offset=Math.multiplyExact(page-1,pageSize);
  List<MediaView> items=repository.catalog(ownerId,mimePrefix,directoryId,tag,keyword,excludeAdult,offset,pageSize);
  long total=repository.catalogCount(ownerId,mimePrefix,directoryId,tag,keyword,excludeAdult);
  List<MediaTagCount> tags=repository.catalogTags(ownerId,mimePrefix,keyword,excludeAdult);
  List<MediaDirectoryCount> directories=repository.catalogDirectories(ownerId,mimePrefix,keyword,excludeAdult);
  return new MediaCatalogPage(items,total,page,pageSize,tags,directories);
 }
 /** 开始分析。 @param id 媒体 @param request 请求 @return 分析 */ public AnalysisView begin(UUID id,BeginAnalysis request){return transactions.execute(s->{MediaView media=repository.view(id).orElseThrow(()->new IllegalArgumentException("media item not found"));if(!media.assetId().equals(request.assetId()))throw new IllegalStateException("media analysis asset identity conflicts");if(!"READY".equals(media.status())&&!"ANALYZING".equals(media.status()))throw new IllegalStateException("media item is not available for analysis");return repository.begin(id,request,Instant.now());});}
 /** 完成分析。 @param id 媒体 @param request 请求 */ public void complete(UUID id,CompleteAnalysis request){validateUniqueResults(request);String hash=digest(request);transactions.executeWithoutResult(s->repository.complete(id,request,hash,Instant.now()));}
 /** 终止失败的分析。 @param id 媒体 @param request 请求 */ public void fail(UUID id,FailAnalysis request){transactions.executeWithoutResult(s->repository.fail(id,request,Instant.now()));}
 /** 同步播放进度。 @param ownerId 所有者 @param id 媒体 @param request 请求 @return 进度 */ public ProgressView progress(long ownerId,UUID id,ProgressRequest request){if(request.durationMs()>0&&request.positionMs()>request.durationMs())throw new IllegalArgumentException("media progress is invalid");return transactions.execute(s->repository.progress(ownerId,id,request,Instant.now()));}
 /** 开始幂等目录扫描。 @param request 请求 @return 扫描 */ public ScanView beginScan(BeginScan request){return transactions.execute(s->repository.beginScan(request,Instant.now()));}
 /** 暂存完整扫描清单。 @param scanId 扫描 @param request 清单 */ public void stageScan(UUID scanId,StageScanEntries request){Set<String> identities=new HashSet<>();for(ScanEntry entry:request.entries())if(!identities.add(entry.sourceBusinessId()))throw new IllegalArgumentException("media scan entry is duplicated");transactions.executeWithoutResult(s->repository.stageScan(scanId,request.entries(),Instant.now()));}
 /** 原子发布已全部导入的扫描。 @param scanId 扫描 @param request 请求 @return 扫描 */ public ScanView finishScan(UUID scanId,FinishScan request){return transactions.execute(s->repository.finishScan(scanId,request.manifestSha256().toLowerCase(),Instant.now()));}
 /** 查询扫描状态。 @param scanId 扫描 @return 扫描 */ public ScanView scan(UUID scanId){return repository.scan(scanId).orElseThrow(()->new IllegalArgumentException("media scan not found"));}
 /** 返回有界媒体关系对账页。 @param afterId 起始标识 @param limit 页大小 @return 对账页 */ @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public ReconciliationPage reconciliation(UUID afterId,int limit){if(limit<1||limit>200)throw new IllegalArgumentException("media reconciliation limit is invalid");long revision=repository.libraryRevision();int directoryCount=repository.count("media_directory",null);int completedScans=repository.count("media_scan","COMPLETED");int stagingScans=repository.count("media_scan","STAGING");List<MediaRepository.ReconciliationSnapshot> values=repository.reconciliationPage(afterId,limit+1);List<MediaRepository.ReconciliationSnapshot> page=values.stream().limit(limit).toList();MessageDigest digest=sha256();update(digest,Long.toString(revision),Integer.toString(directoryCount),Integer.toString(completedScans),Integer.toString(stagingScans));int ready=0,missing=0,analyzing=0,succeeded=0,failed=0,running=0,tags=0,artifacts=0,readyDirectories=0,missingDirectories=0,sources=0,sourceTags=0;for(MediaRepository.ReconciliationSnapshot snapshot:page){var item=snapshot.item();update(digest,item.id().toString(),Long.toString(item.ownerId()),item.assetId().toString(),item.sourceType(),item.sourceBusinessId(),item.contentSha256(),Long.toString(item.sizeBytes()),item.mimeType(),item.status(),Long.toString(item.version()));if("READY".equals(item.status()))ready++;else if("MISSING".equals(item.status()))missing++;else if("ANALYZING".equals(item.status()))analyzing++;for(String value:snapshot.analyses()){update(digest,"ANALYSIS",value);String status=value.split("\\|",-1)[1];if("SUCCEEDED".equals(status))succeeded++;else if("RUNNING".equals(status))running++;else failed++;}for(String value:snapshot.tags())update(digest,"TAG",value);for(String value:snapshot.artifacts())update(digest,"ARTIFACT",value);for(String value:snapshot.directories()){update(digest,"DIRECTORY",value);String status=value.split("\\|",-1)[2];if("READY".equals(status))readyDirectories++;else missingDirectories++;}for(String value:snapshot.sources())update(digest,"SOURCE",value);for(String value:snapshot.sourceTags())update(digest,"SOURCE_TAG",value);tags+=snapshot.tags().size();artifacts+=snapshot.artifacts().size();sources+=snapshot.sources().size();sourceTags+=snapshot.sourceTags().size();}UUID next=values.size()>limit&&!page.isEmpty()?page.getLast().item().id():null;return new ReconciliationPage(next,revision,directoryCount,completedScans,stagingScans,page.size(),sources,sourceTags,ready,missing,analyzing,succeeded,failed,running,tags,artifacts,readyDirectories,missingDirectories,HexFormat.of().formatHex(digest.digest()));}
 /** 解析已迁移旧文件的媒体分析目标。 @param legacyId 旧文件标识 @return 分析目标 */ @Transactional(readOnly=true) public LegacyAnalysisTarget legacyAnalysisTarget(long legacyId){if(legacyId<=0)throw new IllegalArgumentException("legacy media id is invalid");return repository.legacyAnalysisTarget(legacyId).orElseThrow(()->new IllegalArgumentException("legacy media target not found"));}
 /** 创建目录扫描操作。 @param ownerId 所有者 @param request 请求 @return 操作 */ public OperationView startDirectoryScan(long ownerId,StartDirectoryScan request){if(ownerId<=0||request.rootPath().indexOf('\0')>=0)throw new IllegalArgumentException("media scan request is invalid");String requestDigest=digest(request);OperationView existing=repository.findOperation(ownerId,request.idempotencyKey()).orElse(null);if(existing!=null){repository.operationRequestDigest(existing.id()).ifPresent(value->{if(!value.equals(requestDigest))throw new IllegalStateException("media operation idempotency conflict");});return reconcile(existing);}UUID id=UUID.nameUUIDFromBytes((ownerId+"\0"+request.idempotencyKey()).getBytes(StandardCharsets.UTF_8));Map<String,Object>parameters=new HashMap<>();parameters.put("rootPath",request.rootPath());parameters.put("directoryKey",request.directoryKey());parameters.put("directoryName",request.directoryName());parameters.put("ownerId",ownerId);parameters.put("scanKey",request.idempotencyKey());parameters.put("analyze",request.analyze());if(request.analysisVersion()!=null)parameters.put("analysisVersion",request.analysisVersion());String schedulerKey="media-scan:"+ownerId+":"+requestDigest;UUID taskId=scheduler.createScan(id,ownerId,schedulerKey,Map.copyOf(parameters));return transactions.execute(s->repository.saveOperation(id,ownerId,"DIRECTORY_SCAN",request.idempotencyKey(),taskId,requestDigest,Instant.now()));}
 /** 创建媒体分析操作。 @param mediaId 媒体标识 @param ownerId 所有者 @param request 请求 @return 操作 */ public OperationView startAnalysis(UUID mediaId,long ownerId,StartAnalysis request){if(ownerId<=0)throw new IllegalArgumentException("media analysis owner is invalid");MediaView media=view(ownerId,mediaId);String requestDigest=digest(Map.of("mediaId",mediaId,"request",request));OperationView existing=repository.findOperation(ownerId,request.idempotencyKey()).orElse(null);if(existing!=null){if(!"ANALYSIS".equals(existing.operationType())||repository.operationRequestDigest(existing.id()).filter(requestDigest::equals).isEmpty())throw new IllegalStateException("media operation idempotency conflict");return reconcile(existing);}if(!"READY".equals(media.status()))throw new IllegalStateException("media item is not ready for analysis");if(repository.analysisVersionExists(mediaId,request.analysisVersion()))throw new IllegalStateException("media analysis version is already bound");UUID id=UUID.nameUUIDFromBytes((ownerId+"\0ANALYSIS\0"+request.idempotencyKey()).getBytes(StandardCharsets.UTF_8));Map<String,Object>parameters=new HashMap<>();parameters.put("mediaItemId",media.id().toString());parameters.put("assetRegistryId",media.assetId().toString());parameters.put("assetId",media.assetId().toString());parameters.put("analysisVersion",request.analysisVersion());parameters.put("contentSha256",media.contentSha256().toLowerCase(Locale.ROOT));parameters.put("ownerId",ownerId);parameters.put("filename",media.displayName());parameters.put("mimeType",media.mimeType());parameters.put("assetMimeType",media.mimeType());if(request.frameCount()!=null)parameters.put("frameCount",request.frameCount());if(request.seekSeconds()!=null)parameters.put("seekSeconds",request.seekSeconds());String schedulerKey="media-analysis:"+ownerId+":"+mediaId+":"+request.analysisVersion()+":"+requestDigest;UUID taskId=scheduler.createAnalysis(id,schedulerKey,Map.copyOf(parameters));return transactions.execute(s->repository.saveOperation(id,ownerId,"ANALYSIS",request.idempotencyKey(),taskId,requestDigest,Instant.now()));}
 /** 查询所有者操作。 @param id 操作 @param ownerId 所有者 @return 操作 */ public OperationView operation(UUID id,long ownerId){return reconcile(repository.findOperation(id,ownerId).orElseThrow(()->new IllegalArgumentException("media operation not found")));}
 /** 取消所有者操作。 @param id 操作 @param ownerId 所有者 @return 操作 */ public OperationView cancelOperation(UUID id,long ownerId){OperationView value=operation(id,ownerId);if(!Set.of("SUCCEEDED","FAILED","TIMED_OUT","CANCELLED").contains(value.status()))scheduler.cancel(value.taskInstanceId());return reconcile(value);}
 private OperationView reconcile(OperationView value){String status=scheduler.status(value.taskInstanceId());return status.equals(value.status())?value:transactions.execute(s->repository.updateOperation(value.id(),status,Instant.now()));}
 private String digest(Object value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(mapper.writeValueAsBytes(value)));}catch(NoSuchAlgorithmException|java.io.IOException exception){throw new IllegalStateException("media payload digest failed",exception);}}
 private String legacyPayloadDigest(LegacyMediaImport request){MessageDigest value=sha256();AssetEvent event=request.event();update(value,event.eventId(),event.assetId().toString(),Long.toString(event.ownerId()),event.sourceType(),event.sourceBusinessId(),event.displayName(),event.mimeType(),Long.toString(event.sizeBytes()),event.contentSha256().toLowerCase(Locale.ROOT),event.directoryKey(),event.directoryName(),event.scanId()==null?null:event.scanId().toString());request.tags().stream().sorted(Comparator.comparing(tag->tag.name().trim().toLowerCase(Locale.ROOT))).forEach(tag->update(value,tag.name().trim().toLowerCase(Locale.ROOT),confidence(tag.confidence())));return HexFormat.of().formatHex(value.digest());}
 private String confidence(Double value){return value==null?null:java.math.BigDecimal.valueOf(value).setScale(5,java.math.RoundingMode.HALF_UP).toPlainString();}
 private MessageDigest sha256(){try{return MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException exception){throw new IllegalStateException("SHA-256 is unavailable",exception);}}
 private void update(MessageDigest digest,String...values){for(String value:values){byte[] bytes=Objects.toString(value,"").getBytes(StandardCharsets.UTF_8);digest.update(ByteBuffer.allocate(Integer.BYTES).putInt(bytes.length).array());digest.update(bytes);}}
 private void validateUniqueResults(CompleteAnalysis request){validateTags(request.tags()==null?List.of():request.tags());Set<String> artifacts=new HashSet<>();for(ArtifactInput artifact:request.artifacts()==null?List.<ArtifactInput>of():request.artifacts())if(!artifacts.add(artifact.kind()+"\0"+artifact.generatorVersion()))throw new IllegalArgumentException("media artifact version is duplicated");}
 private void validateTags(List<TagInput>values){Set<String> tags=new HashSet<>();for(TagInput tag:values)if(!tags.add(tag.name().trim().toLowerCase(Locale.ROOT)))throw new IllegalArgumentException("media tag is duplicated");}
}
